const imageUrls = $('Webhook').first().json.body.image;
const dirName = $('Webhook').first().json.body.article_id;

const results = [];
for (let i = 0; i < imageUrls.length; i++) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: imageUrls[i],
    encoding: 'arraybuffer',
    returnFullResponse: true,
  });
  const fileName = `image_${i + 1}.jpg`;
  results.push({
    json: { fileName, dirName, url: imageUrls[i], status: 'downloaded' },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(response.body),
        fileName,
        'image/jpeg'
      ),
    },
  });
}
return results;

const title = $('Webhook').first().json.body.title;
const text = $('Webhook').first().json.body.text;
const dirName = $('Webhook').first().json.body.article_id;

// 파일명에 쓸 수 없는 문자 제거
const safeTitle = title.replace(/[\/\\:"<>|?*']/g, '');

return [{
  json: {
    title: safeTitle,
    text: text,
    dirName
  }
}];

const content = $input.first().json.message.content;
const subtitles = JSON.parse(content);
const dirName = $('Webhook').first().json.body.article_id;

let srt = '';
for (let i = 0; i < subtitles.length; i++) {
  const start = i * 3;
  const end = start + 3;
  const startTime = `00:00:0${start},000`;
  const endTime = `00:00:0${end},000`;
  srt += `${i + 1}\n${startTime} --> ${endTime}\n${subtitles[i]}\n\n`;
}
return [{
  json: { fileName: 'subtitles.srt', dirName },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(srt, 'utf-8'),
      'subtitles.srt',
      'text/plain'
    ),
  },
}];
